use ingetrazo_core::sheet_shape::{SheetShape,ShapePath};
use serde_json::json;
fn main(){let args=std::env::args().collect::<Vec<_>>();let shapes:Vec<SheetShape>=serde_json::from_slice(&std::fs::read(&args[1]).unwrap()).unwrap();let rows=shapes.into_iter().map(|shape|shape.paint_commands(100_000).unwrap().into_iter().map(|c|{let path=match c.path {ShapePath::RoundedRect{size,radius}=>json!({"rect":size.to_array(),"radius":radius}),ShapePath::Ellipse{size}=>json!({"ellipse":size.to_array()}),ShapePath::Polygon(p)=>json!({"polygon":p.iter().map(|p|p.to_array()).collect::<Vec<_>>()}),ShapePath::Line(a,b)=>json!({"line":[a.to_array(),b.to_array()]})};json!({"path":path,"stroke":c.stroke,"fill":c.fill})}).collect::<Vec<_>>()).collect::<Vec<_>>();std::fs::write(&args[2],serde_json::to_vec_pretty(&rows).unwrap()).unwrap();}
